import {MODE_NAMES,modeConfig,modeDescription} from './modes.js';
import {CHARACTERS} from './content.js';import {portrait} from './portraits.js';import {setupError} from './setup.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function advancedPanel(draft,character,count,difficulty){
 const primary=draft.character||character;
 const seats=Array.from({length:count},(_,i)=>{
  const id=i?draft.opponents[i-1]||'random':primary,level=i?draft.seatLevels[i-1]||'inherit':draft.primaryLevel||'inherit',type=draft.seatTypes[i]||(i?'ai':'human');
  return `<div class="opponent-seat"><span class="seat-portrait">${id==='random'?'<span class="random-face">⚄</span>':portrait(id)}</span><div><label>席位 ${i+1} 角色<select ${i?`data-setup-seat="${i-1}"`:'data-setup-primary'} aria-label="席位${i+1}角色">${i?'<option value="random">随机角色</option>':''}${CHARACTERS.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div class="seat-controls"><label>控制类型<select data-setup-type="${i}" aria-label="席位${i+1}类型"><option value="human" ${type==='human'?'selected':''}>真人</option><option value="ai" ${type==='ai'?'selected':''}>电脑</option></select></label><label>AI 难度<select ${i?`data-setup-level="${i-1}"`:'data-setup-primary-level'} aria-label="席位${i+1}难度">${[['inherit','跟随全局'],['easy','轻松'],['normal','标准'],['hard','高手']].map(([key,name])=>`<option value="${key}" ${level===key?'selected':''}>${name}</option>`).join('')}</select></label></div></div>`;
 }).join('');
 return `<p class="panel-note">每个席位独立选择真人或电脑、角色与AI难度。两名以上真人采用换手确认；全部电脑可旁观。角色不重复，随机角色会避开固定角色。</p><div id="opponentSeats">${seats}</div><div class="row-actions"><button class="secondary" data-act="allRandom">其余角色随机</button></div><h3>旅行模式</h3><label>模式<select id="setupMode">${Object.entries(MODE_NAMES).map(([id,name])=>`<option value="${id}" ${draft.modeId===id?'selected':''}>${name}</option>`).join('')}</select></label><p id="modeDescription" class="panel-note">${modeDescription(modeConfig({id:draft.modeId, cash:draft.startingCash,tickets:draft.startingTickets}))}</p><p>短局、经营和每日模式固定轮数与起始条件，覆盖下方自定义资产；地图、席位、角色仍按所选设置。经营挑战每席获两块按地图顺序分配的一级住宅、3200现金、800贷款，禁用抢地、拆除、换位卡。每日挑战由本地日期生成种子；改日期或存档即可作弊，非竞赛认证。同日仅在所有其他设置相同时可复现。</p><h3>自定义经典规则</h3><div class="setup-grid"><label>初始奶币<select id="setupCash">${[2000,3200,5000,8000].map(n=>`<option ${draft.startingCash===n?'selected':''}>${n}</option>`).join('')}</select></label><label>初始点券<select id="setupTickets">${[0,60,120].map(n=>`<option ${draft.startingTickets===n?'selected':''}>${n}</option>`).join('')}</select></label><label>地图<select id="setupMap"><option value="2" ${draft.mapVersion===2?'selected':''}>奶家滨河镇</option><option value="1" ${draft.mapVersion===1?'selected':''}>经典发财岛</option></select></label><label>先手<select id="setupInitiative"><option value="random" ${draft.randomStart?'selected':''}>随机先手</option><option value="human" ${!draft.randomStart?'selected':''}>第一席位先出发</option></select></label><label class="setup-seed">对局种子<input id="setupSeed" ${draft.modeId==='daily'?'disabled':''} type="text" inputmode="numeric" maxlength="10" value="${esc(draft.seed)}" placeholder="留空随机；相同设置可复现"></label></div><p class="stock-explain">真人忽略AI难度。同一模式内各席使用相同初始资产配置和规则，类型和角色会随存档保存。</p><p id="setupError" class="setup-error" role="status">${esc(setupError(draft,primary,count))}</p><div class="button-grid"><button class="secondary" data-act="resetAdvanced">恢复默认</button><button class="primary" data-act="applyAdvanced" ${setupError(draft,primary,count)?'disabled':''}>保存设置</button></div>`;
}
